   foreach(var animationEdge in new[]{Edge.Left,Edge.Right,Edge.Top,Edge.Bottom}){
    bool vertical=animationEdge is Edge.Left or Edge.Right;double width=vertical?52:400,height=vertical?400:52;var fixture=new Border{Width=width,Height=height,Background=Ui.Brush("#203040",Brushes.Black)};fixture.Measure(new Size(width,height));fixture.Arrange(new Rect(0,0,width,height));fixture.UpdateLayout();var monitor=monitors[0];var bounds=new Bounds(monitor.Bounds.X,monitor.Bounds.Y,width*monitor.Scale,height*monitor.Scale);
    var frame=new BarAnimationWindow(fixture,new Bar{Edge=animationEdge,Opacity=1},monitor,bounds,0);frame.Show();await Task.Delay(80);Check(frame.Ready&&frame.AllowsTransparency,"Composited animation surface is ready on "+animationEdge);
    foreach(double progress in new[]{0d,.05,.25,.5,1}){frame.SetProgress(progress);frame.UpdateLayout();var image=new RenderTargetBitmap((int)(width*monitor.Scale),(int)(height*monitor.Scale),96*monitor.Scale,96*monitor.Scale,PixelFormats.Pbgra32);image.Render(frame.Frame);byte[] pixels=new byte[image.PixelWidth*image.PixelHeight*4];image.CopyPixels(pixels,image.PixelWidth*4,0);int visible=0;bool bright=false;for(int i=0;i<pixels.Length;i+=4){if(pixels[i+3]>0)visible++;if(pixels[i]>100||pixels[i+1]>100||pixels[i+2]>100)bright=true;}double coverage=(double)visible/(image.PixelWidth*image.PixelHeight);Check(!bright&&Math.Abs(coverage-progress)<.025,$"{animationEdge} frame at {progress:P0} has expected coverage without bright fragments");if(animationEdge==Edge.Left){var encoder=new PngBitmapEncoder();encoder.Frames.Add(BitmapFrame.Create(image));using var stream=File.Create(Path.Combine(output,$"animation-left-{(int)(progress*100):D3}.png"));encoder.Save(stream);}}
    frame.Close();
