   b.Edge=Edge.Left;b.Alignment=Alignment.Center;b.Visibility=VisibilityMode.AutoHide;b.HideDelay=10000;app.RebuildBars();await Task.Delay(100);var edgeBar=app.Bars[0];var edgeHandle=new WindowInteropHelper(edgeBar).Handle;edgeBar.ToggleReveal();await Task.Delay(50);Check(!SystemParameters.ClientAreaAnimation||edgeBar.IsAnimating&&edgeBar.RevealProgress is >0 and <1,"Auto-hide uses intermediate animation frames");await Task.Delay(230);Check(edgeBar.IsHidden&&!Native.IsWindowVisible(edgeHandle),"Hidden edge has no visible activation line outside Settings");
