   b.Visibility=VisibilityMode.AutoHide;b.FloatingReveal=FloatingReveal.Both;b.Hotkey="Ctrl+Alt+F10";app.RebuildBars();await Task.Delay(250);var first=app.Bars[0];first.ToggleReveal();await Task.Delay(280);Native.GetWindowRect(new WindowInteropHelper(first).Handle,out var hidden);Check(hidden.Height<=12*first.Monitor.Scale,"Floating auto-hide activation tab");first.ToggleReveal();await Task.Delay(280);Native.GetWindowRect(new WindowInteropHelper(first).Handle,out var shown);Check(shown.Height>=32,"Floating reveal restores size");
   b.Visibility=VisibilityMode.Overlay;app.RebuildBars();var popup=new GroupWindow(app.Bars[0],group);popup.Show();await Task.Delay(200);Check(popup.IsLoaded,"Linked-folder popup opens");Check(popup.WindowStyle==WindowStyle.None,"Groups have no native title bar");popup.BeginRename();popup.CommitRename("Project resources");Check(popup.Group.Name=="Project resources"&&popup.Group.Target==testFolder&&Directory.Exists(testFolder),"Inline group rename updates only its label");Render(popup,Path.Combine(output,"group.png"));popup.SetLabels(false);Check(Find<Button>(popup).Where(x=>x.ToolTip is string).All(x=>x.Content is not StackPanel p||!p.Children.OfType<TextBlock>().Any(label=>label.Text==x.ToolTip?.ToString())),"Group icons-only mode removes visible item labels");Render(popup,Path.Combine(output,"group-icons-only.png"));popup.Close();
   var menu=app.Bars[0].ContextMenu;var newMenu=menu.Items.OfType<MenuItem>().Single(x=>Equals(x.Header,"New"));Check(newMenu.Items.Count==8&&!menu.Items.OfType<MenuItem>().Any(x=>(x.Header?.ToString()??"").StartsWith("Add ")),"Bar creation actions are grouped into New submenu");
   var cueBar=app.Bars[0];var cueTarget=Find<Button>(cueBar).Last(x=>x.Tag is Item);var dragData=new DataObject();dragData.SetData("DockForge.Item",b.Items[0]);dragData.SetData("DockForge.Bar",b.Id);var dragPoint=cueTarget.TranslatePoint(new Point(cueTarget.ActualWidth*.9,cueTarget.ActualHeight/2),cueBar);cueBar.ShowInsertionPreview(dragData,dragPoint);Check(cueBar.DropIndicator.Visibility==Visibility.Visible&&cueBar.DropIndicator.Width==3,"Horizontal drag shows an insertion marker");Render(cueBar,Path.Combine(output,"bar-drop-cue.png"));cueBar.Model.Locked=true;cueBar.ShowInsertionPreview(dragData,dragPoint);Check(cueBar.DropIndicator.Visibility==Visibility.Collapsed,"Locked bars suppress insertion markers");cueBar.Model.Locked=false;
   string linkPath=Path.Combine(testFolder,"Explorer.lnk");dynamic script=Activator.CreateInstance(Type.GetTypeFromProgID("WScript.Shell")!)!;dynamic link=script.CreateShortcut(linkPath);link.TargetPath=b.Items[0].Target;link.Save();System.Runtime.InteropServices.Marshal.FinalReleaseComObject(link);System.Runtime.InteropServices.Marshal.FinalReleaseComObject(script);Check(ReferenceEquals(ShellService.Icon(new Item{Target=linkPath},true),ShellService.Icon(b.Items[0])),"Shortcut badge hiding uses the unbadged target icon");
   Check(ShellService.Icon(new Item{Target=Path.Combine(testFolder,"beta.url")},true)==null,"Internet shortcut badge hiding uses a clean website glyph");
   var installed=ShellService.InstalledApps();Check(installed.Count>0,"Installed desktop and Store app enumeration");Check(ShellService.Icon(b.Items[0])!=null,"Windows shell icon extraction");
   var settings=new SettingsWindow(false,b);settings.Show();await Task.Delay(250);Check(settings.IsLoaded,"Central settings opens");Render(settings,Path.Combine(output,"settings.png"));
   var innerTabs=Find<TabControl>(settings).First(t=>t.Items.OfType<TabItem>().Any(i=>Equals(i.Header,"Appearance")));
   innerTabs.SelectedItem=innerTabs.Items.OfType<TabItem>().First(t=>Equals(t.Header,"Appearance"));settings.UpdateLayout();await Task.Delay(150);Render(settings,Path.Combine(output,"settings-appearance.png"));
   var iconSize=Find<TextBox>(settings).Single(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="Icon size (16–96)");var thickness=Find<TextBox>(settings).Single(x=>System.Windows.Automation.AutomationProperties.GetName(x)=="Bar thickness");thickness.Text="140";iconSize.Text="48";Check(b.Thickness==Layout.MinimumThickness(48,b.Spacing)&&double.Parse(thickness.Text)==b.Thickness,"Icon growth resets thickness to the optimal minimum");iconSize.Text="24";Check(b.Thickness==Layout.MinimumThickness(24,b.Spacing),"Icon reduction also reduces thickness");thickness.Text="120";Check(b.Thickness==120,"User can increase thickness after automatic sizing");
   var form=Find<ResponsiveForm>(settings).First(f=>f.IsVisible);Check(form.ActualWidth>=620,"Settings uses two-column layout at standard width");
   Check(Find<ScrollViewer>(settings).Where(v=>v.IsVisible&&v.Content is ResponsiveForm).All(v=>v.ScrollableHeight<1),"Appearance settings fit without scrolling at standard size");
   settings.Width=720;settings.Height=650;settings.UpdateLayout();await Task.Delay(150);Render(settings,Path.Combine(output,"settings-narrow.png"));Check(form.ActualWidth<620,"Settings reflows at narrow width");
   Check(Find<Button>(settings).Where(x=>x.IsVisible&&Equals(x.Content,"Save and close")).All(x=>x.ActualWidth>80),"Settings footer remains usable at narrow width");
   var globalTabs=Find<TabControl>(settings).Single(t=>t.Items.OfType<TabItem>().Any(i=>Equals(i.Header,"Backups & updates")));globalTabs.SelectedItem=globalTabs.Items.OfType<TabItem>().Single(i=>Equals(i.Header,"Backups & updates"));settings.UpdateLayout();await Task.Delay(150);Render(settings,Path.Combine(output,"settings-updates.png"));Check(Find<TextBlock>(settings).Any(t=>t.IsVisible&&t.Text=="Official update source: sidosgr/DockForge"),"Settings displays the fixed official update repository");Check(!Find<TextBox>(settings).Any(t=>t.IsVisible&&System.Windows.Automation.AutomationProperties.GetName(t).Contains("repository")),"Settings does not offer an editable repository redirect");var previewToggle=Find<CheckBox>(settings).Single(t=>t.Content is TextBlock label&&label.Text=="Include development previews");previewToggle.IsChecked=false;Check(!app.Config.IncludePreviewUpdates,"Preview update toggle changes the active preference");settings.Close();Check(app.Config.IncludePreviewUpdates,"Cancel restores the preview update preference");
   var help=HelpContent.QuickStart();Check(!Find<TextBlock>(help).Any(x=>x.Text.TrimStart().StartsWith("#")),"Quick help contains formatted content instead of Markdown");Check(File.Exists(Path.Combine(AppContext.BaseDirectory,"Help.html")),"Complete HTML guide is bundled with the application");
   var wizard=new SetupWizard();wizard.Show();await Task.Delay(150);Check(wizard.IsLoaded,"First-run wizard opens");Render(wizard,Path.Combine(output,"wizard.png"));wizard.Close();
   var available=app.Windows.Enumerate();lines.Add("INFO Eligible running windows: "+available.Count);if(available.Count>0){var picker=new WindowPicker(app.Bars[0],available.Take(2).ToList(),false);picker.Show();await Task.Delay(200);Check(picker.IsLoaded,"Window picker opens");Check(picker.WindowStyle==WindowStyle.None,"Window previews have no native title bar");Check(!Find<ScrollViewer>(picker).Any(),"Window previews contain no scrollbars");Check(picker.ActualWidth<=picker.MaxWidth&&picker.ActualHeight<=picker.MaxHeight,"Preview fits its display");picker.Close();var hoverBar=app.Bars[0];var anchor=Find<Button>(hoverBar).First(x=>x.Tag is Item);hoverBar.PreviewForTest(available.Take(1).ToList(),anchor);Check(hoverBar.HoverPreviewOpen,"Hover preview opens from an app icon");anchor.RaiseEvent(new System.Windows.Input.MouseEventArgs(System.Windows.Input.Mouse.PrimaryDevice,0){RoutedEvent=System.Windows.Input.Mouse.MouseLeaveEvent});Check(!hoverBar.HoverPreviewOpen&&!hoverBar.OwnedWindows.OfType<WindowPicker>().Any(),"Leaving the app icon dismisses the hover preview immediately");hoverBar.PreviewForTest(available.Take(1).ToList(),anchor,true);anchor.RaiseEvent(new System.Windows.Input.MouseEventArgs(System.Windows.Input.Mouse.PrimaryDevice,0){RoutedEvent=System.Windows.Input.Mouse.MouseLeaveEvent});Check(hoverBar.OwnedWindows.OfType<WindowPicker>().Any(),"Explicit close-window picker stays available after leaving the icon");foreach(var closePicker in hoverBar.OwnedWindows.OfType<WindowPicker>().ToArray())closePicker.Close();}
   string journal=Path.Combine(output,"guard-fixture.json");File.WriteAllText(journal,"[]");string readyName="Local\\DockForge.SmokeGuard."+Guid.NewGuid();using(var ready=new EventWaitHandle(false,EventResetMode.ManualReset,readyName)){using var parent=Process.Start(new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,ArgumentList={"--guard-fixture"}})!;using var guard=Process.Start(new ProcessStartInfo(Environment.ProcessPath!){UseShellExecute=false,CreateNoWindow=true,ArgumentList={"--guard",parent.Id.ToString(),parent.StartTime.ToUniversalTime().Ticks.ToString(),journal,readyName}})!;Check(await Task.Run(()=>ready.WaitOne(5000)),"Recovery helper signals readiness");await parent.WaitForExitAsync();await guard.WaitForExitAsync().WaitAsync(TimeSpan.FromSeconds(8));Check(guard.ExitCode==0&&File.ReadAllText(journal)=="[]","Recovery helper exits after monitored parent ends");}
   var before=app.Config.Clone();app.Config.Bars[0].Name="Temporary edit";app.Config=before;Check(app.Config.Bars[0].Name=="DockForge preview","Settings snapshot restores bar state");
